/* MERIDIAN economy expansion: compatible with v1 local campaigns. */
'use strict';
const GOODS=[
 {name:'Продукты',base:420,license:'cold',loss:.03},
 {name:'Металлы',base:850,license:null,loss:0},
 {name:'Комплектующие',base:1900,license:null,loss:0},
 {name:'Электроника',base:4100,license:null,loss:0}
];
const REGIONAL=[[.9,1.15,1,1.22],[1.08,.85,.86,.78],[1.2,1,1.16,1.1],[1.22,.7,1.25,1.36],[.8,1.2,1.3,1.3]];
const RECIPES=[{name:'Завод комплектующих',input:1,output:2,ratio:1.4,batch:4,cost:74000,labor:850},{name:'Сборка электроники',input:2,output:3,ratio:1.3,batch:2,cost:125000,labor:1300}];
let marketRegion=0;
function econInit(){if(!state.economy){state.economy={inventory:{},pressure:{},plants:[],profit:0,sales:0,storage:0,spoilage:0,records:[],nextPlant:1};}return state.economy;}
function stock(r,g){const e=econInit(),key=r+':'+g;return e.inventory[key]||(e.inventory[key]={qty:0,basis:0});}
function stockWeight(r){return GOODS.reduce((n,_,g)=>n+stock(r,g).qty,0)}
function incoming(r){return state.jobs.filter(j=>j.trade&&j.d===r).reduce((n,j)=>n+j.trade.qty,0)}
const oldLoad=load;
load=r=>oldLoad(r)+stockWeight(r)+incoming(r);
function marketPrice(r,g,shift=0){const e=econInit(),p=Math.max(-.22,Math.min(.22,(e.pressure[r+':'+g]||0)+shift)),wave=1+.09*Math.sin(state.day*.25+r*1.5+g),mid=GOODS[g].base*REGIONAL[r][g]*wave*(1+p);return {buy:Math.ceil(mid*1.06),sell:Math.floor(mid*.94)};}
function recordProfit(n,text){const e=econInit();e.profit+=n;e.records.unshift({day:state.day,text,profit:n});e.records=e.records.slice(0,40)}
function moveMarket(r,g,n){const e=econInit(),k=r+':'+g;e.pressure[k]=Math.max(-.22,Math.min(.22,(e.pressure[k]||0)+n*.002));}
function accessGood(g){return !GOODS[g].license||state.tech.includes(GOODS[g].license)}
function purchaseStock(r,g,qty){if(!state.regions.includes(r)||!GOODS[g]||!Number.isInteger(qty)||qty<1||qty>100||!accessGood(g))return;const price=marketPrice(r,g,qty*.001).buy*qty;if(load(r)+qty>capacity(r)){notify('На складе недостаточно места');return}if(!spend(price,'Закупка: '+GOODS[g].name+' · '+regions[r].name))return;const s=stock(r,g);s.qty+=qty;s.basis+=price;moveMarket(r,g,qty);render();notify('Груз принят на склад');}
function sellStock(r,g,qty){if(!state.regions.includes(r)||!GOODS[g]||!Number.isFinite(qty)||qty<=0)return;const s=stock(r,g);qty=Math.min(qty,s.qty);if(!qty)return;const basis=s.basis*qty/s.qty,revenue=marketPrice(r,g,-qty*.001).sell*qty;s.qty-=qty;s.basis-=basis;transaction(revenue,'Продажа: '+GOODS[g].name);econInit().sales+=revenue;recordProfit(revenue-basis,'Продажа '+GOODS[g].name);moveMarket(r,g,-qty);render();notify('Продано на '+money(revenue)+' · результат '+money(revenue-basis));}
function vector(type){const shapes={truck:'<path d="M3 7h22v16H3zM25 13h8l7 7v3H25"/><circle cx="11" cy="25" r="4"/><circle cx="32" cy="25" r="4"/>',rail:'<rect x="4" y="5" width="34" height="18" rx="3"/><path d="M10 6v11h9V6m4 0v11h9V6M2 30h40M9 24l-3 6m28-6 3 6"/>',ship:'<path d="M2 20h39l-7 10H11zM10 20V8h9v12m3 0V8h9v12M3 34q6-4 12 0t12 0t12 0"/>',plane:'<path d="M21 2l4 13 15 9v4l-15-5v9l5 4H12l5-4v-9L2 28v-4l15-9z"/>',warehouse:'<path d="M2 14L22 3l20 11M6 12v24h32V12M15 36V20h14v16M12 12h20"/>',box:'<path d="M4 12L22 3l18 9v20l-18 9L4 32zM4 12l18 9 18-9M22 21v20M13 7l18 9v9"/>',factory:'<path d="M4 37V18l12-7v9l12-9v9h11v17zM31 20V4h7v16M10 28h5m5 0h5m5 0h5"/>',coins:'<ellipse cx="21" cy="9" rx="16" ry="6"/><path d="M5 9v10c0 8 32 8 32 0V9M5 19v10c0 8 32 8 32 0V19"/>'};return `<svg class="econ-icon" viewBox="0 0 44 44" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${shapes[type]||shapes.box}</svg>`;}
function typeIcon(t){return ['truck','truck','rail','ship','plane','truck'][t]}
function shipmentVisual(j){const progress=Math.max(0,Math.min(1,1-j.remaining/j.total)),vehicle=state.fleet.find(v=>v.id===j.vehicle),x=30+progress*290;return `<div class="shipment-art"><svg viewBox="0 0 350 60" role="img" aria-label="Рейс выполнен на ${Math.round(progress*100)} процентов"><path d="M30 38H320" stroke="#344956" stroke-width="2" stroke-dasharray="5 6"/><path d="M30 38H${x}" stroke="#b6ed65" stroke-width="3"/><circle cx="30" cy="38" r="5" fill="#b6ed65"/><circle cx="320" cy="38" r="5" fill="#74bdf5"/><g class="moving-cargo" transform="translate(${x-9} 17)"><rect width="18" height="16" rx="3" fill="#b6ed65"/><path d="M9 0v16M0 5h18" stroke="#152119"/></g></svg><div class="inline">${vector(typeIcon(vehicle?.type||0))}<small>${j.trade?'Собственный товар':j.reposition?'Перебазирование':'Контрактный груз'} · ${j.remaining} дн. до прибытия</small></div></div>`;}
function networkDiagram(){const pos=[[55,50],[185,50],[315,50],[120,150],[260,150]];return `<svg class="network-diagram" viewBox="0 0 370 190" role="img" aria-label="Схема пяти рынков и активных межрегиональных рейсов">${state.jobs.filter(j=>j.r!==j.d).map(j=>{const a=pos[j.r],b=pos[j.d];return `<path class="network-route" d="M${a}L${b}" fill="none" stroke="#b6ed65" stroke-width="2" stroke-dasharray="5 5"/>`}).join('')}${regions.map((r,i)=>`<circle cx="${pos[i][0]}" cy="${pos[i][1]}" r="20" fill="${state.regions.includes(i)?'#283f29':'#18232d'}" stroke="${state.regions.includes(i)?'#b6ed65':'#526574'}"/><text x="${pos[i][0]}" y="${pos[i][1]+5}" text-anchor="middle" fill="#e8eef3" font-size="14">${r.code}</text><text x="${pos[i][0]}" y="${pos[i][1]+39}" text-anchor="middle" fill="#aabcc9" font-size="12">${r.name}</text>`).join('')}</svg>`;}
function tradeView(){econInit();if(!state.regions.includes(marketRegion))marketRegion=0;const r=marketRegion;return `<div class="panel"><div class="row"><h2>${vector('coins')} Товарная торговля</h2><label>Рынок <select onchange="marketRegion=Number(this.value);render()">${state.regions.map(i=>`<option value="${i}" ${i===r?'selected':''}>${regions[i].name}</option>`).join('')}</select></label></div><p>Покупайте товар, перевозите своим парком и продавайте там, где спрос выше. Цены партии учитывают её объём и спред; продажи снижают локальную цену, покупки повышают. В день рынок восстанавливается на 20%.</p><div class="callout">Склад: ${stockWeight(r).toFixed(1)} т товаров · ${incoming(r).toFixed(1)} т ожидается · занято ${load(r).toFixed(1)} / ${capacity(r)} т с учётом контрактов. Хранение: 2 $ за тонну в день. Продукты теряют 3% остатка ежедневно.</div><div class="grid">${GOODS.map((g,i)=>{const p=marketPrice(r,i),s=stock(r,i);return `<div class="card"><div class="row">${vector('box')}<h3>${g.name}</h3><span class="badge">${s.qty.toFixed(1)} т</span></div><div class="metric"><span>Купить / продать 1 т</span><strong>${money(p.buy)} / ${money(p.sell)}</strong></div><div class="metric"><span>Средняя себестоимость</span><span>${s.qty?money(s.basis/s.qty):'—'} / т</span></div><div class="metric"><span>Оценка прибыли при продаже</span><strong class="${s.qty*p.sell-s.basis>=0?'positive':'negative'}">${money(s.qty*p.sell-s.basis)}</strong></div><div class="inline"><button ${!accessGood(i)?'disabled':''} onclick="purchaseStock(${r},${i},5)">Купить 5 т</button><button ${!s.qty?'disabled':''} onclick="sellStock(${r},${i},5)">Продать до 5 т</button><button ${!s.qty?'disabled':''} onclick="tradeModal(${r},${i})">Перевезти</button></div>${!accessGood(i)?'<p>Для закупки нужна холодовая цепь.</p>':''}</div>`}).join('')}</div></div><div class="panel"><h2>Цены продажи по рынкам, $ / т</h2><div class="tablewrap"><table><thead><tr><th>Рынок</th>${GOODS.map(g=>`<th>${g.name}</th>`).join('')}</tr></thead><tbody>${regions.map((region,i)=>`<tr><td>${region.name} ${state.regions.includes(i)?'':'· закрыт'}</td>${GOODS.map((_,g)=>`<td>${money(marketPrice(i,g).sell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>Прогноз использует сегодняшние цены. К моменту доставки они изменятся.</p></div>${productionView(r)}`;}
function tradeQuote(r,g,d,v,qty){const dist=6500+Math.abs(d-r)*850,m=modes[v.type],fuel=Math.ceil(dist*m.fuel*(state.tech.includes('eco')?.85:1)),days=Math.ceil(dist/m.speed*(state.tech.includes('dispatch')?.8:1)),s=stock(r,g),basis=s.qty?s.basis*qty/s.qty:0,fee=Math.round(basis*.04),insurance=Math.round(basis*.02),outlay=fee+insurance+Math.max(0,fuel-state.fuel)*state.fuelPrice,cost=fee+insurance+fuel*state.fuelPrice,operating=(m.crew+m.maint)*days,risk=Math.max(.01,.035+(100-v.condition)/450+state.event.risk-(state.tech.includes('risk')?.04:0));return {dist,fuel,days,basis,fee,insurance,outlay,cost,operating,risk,profit:marketPrice(d,g).sell*qty-basis-cost-operating};}
function tradeModal(r,g){const dest=state.regions.filter(i=>i!==r),vs=state.fleet.filter(v=>!busy(v.id)&&v.location===r&&[3,4].includes(v.type)&&v.condition>=30);modal(`<h2>Перевозка: ${GOODS[g].name}</h2><p>Межконтинентальный рейс: самолёт или судно. Страхование включено: защищает стоимость товара, но не срок доставки. Один транспорт — один груз.</p><label>Регион назначения<select id="trade-d" onchange="showTradeQuote(${r},${g})">${dest.map(i=>`<option value="${i}">${regions[i].name}</option>`).join('')}</select></label><label>Транспорт<select id="trade-v" onchange="showTradeQuote(${r},${g})">${vs.map(v=>`<option value="${v.id}">${modes[v.type].name} #${v.id} · ${modes[v.type].cap} т</option>`).join('')}</select></label><label>Тонны<input id="trade-qty" type="number" min="1" step="1" value="${Math.max(1,Math.min(5,Math.floor(stock(r,g).qty)))}" oninput="showTradeQuote(${r},${g})"></label><div id="trade-quote"></div><div class="actions"><button onclick="closeModal()">Отмена</button><button id="trade-send" class="primary" onclick="sendTrade(${r},${g})">Отправить</button></div>`);showTradeQuote(r,g);}
function readTrade(r,g){if(!state.regions.includes(r)||!GOODS[g])return null;const d=Number($('#trade-d').value),v=state.fleet.find(v=>v.id===Number($('#trade-v').value)),qty=Number($('#trade-qty').value);if(!v||!state.regions.includes(d)||d===r||!Number.isInteger(qty)||qty<1||qty>stock(r,g).qty||qty>modes[v.type].cap||busy(v.id)||v.location!==r||![3,4].includes(v.type)||v.condition<30)return null;return {d,v,qty,q:tradeQuote(r,g,d,v,qty)};}
function showTradeQuote(r,g){const a=readTrade(r,g);$('#trade-send').disabled=true;if(!a){$('#trade-quote').innerHTML='<p>Нужны второй рынок, свободный самолёт или судно и целое количество имеющегося товара в пределах вместимости.</p>';return}const {d,qty,q}=a;$('#trade-quote').innerHTML=`<div class="metric"><span>Топливо, сборы и страховка</span><strong>${money(q.cost)}</strong></div><div class="metric"><span>Транспорт в пути</span><strong>${money(q.operating)}</strong></div><div class="metric"><span>Прогноз маржи</span><strong class="${q.profit>=0?'positive':'negative'}">${money(q.profit)}</strong></div><p>${q.days} дней · ${q.fuel} л · риск задержки на 2 дня ${pct(q.risk)}. Сейчас спишется ${money(q.outlay)}. Продажа по прибытии вручную. Общие расходы складов, хранения и проценты не входят в прогноз.</p>${load(d)+qty>capacity(d)?'<p class="negative">Недостаточно места на складе назначения.</p>':''}`;$('#trade-send').disabled=state.cash<q.outlay||load(d)+qty>capacity(d);}
function sendTrade(r,g){const a=readTrade(r,g);if(!a)return;const {v,d,qty,q}=a;if(load(d)+qty>capacity(d)||state.cash<q.outlay)return;const s=stock(r,g);transaction(-q.outlay,'Собственный груз: '+GOODS[g].name);state.fuel=Math.max(0,state.fuel-q.fuel);s.qty-=qty;s.basis-=q.basis;const incident=seed(state.uid*67+state.day)<q.risk,days=q.days+(incident?2:0);state.jobs.push({id:state.uid++,vehicle:v.id,r,d,g:[1,2,7,0][g],from:regions[r].name,to:regions[d].name,weight:0,pay:0,dist:q.dist,remaining:days,total:days,reposition:true,trade:{g,qty,basis:q.basis+q.cost,incident}});closeModal();render();notify(incident?'Груз отправлен. Ожидается задержка на 2 дня.':'Собственный груз отправлен');}
function productionView(r){const e=econInit();return `<div class="panel"><h2>${vector('factory')} Производственные цепочки</h2><p>Сырьё → комплектующие → электроника. Заводы автоматически расходуют складские запасы при завершении дня. Покупка завода и запуск производства — отдельные решения.</p><div class="grid">${RECIPES.map((p,t)=>`<div class="card"><h3>${p.name}</h3><p>${(p.batch*p.ratio).toFixed(1)} т ${GOODS[p.input].name.toLowerCase()} → ${p.batch} т ${GOODS[p.output].name.toLowerCase()} / день</p><p>Обработка: ${money(p.labor)}/день работы · содержание: 150 $/день всегда.</p><button onclick="buildPlant(${r},${t})" ${state.cash<p.cost?'disabled':''}>Построить · ${money(p.cost)}</button></div>`).join('')}</div>${e.plants.filter(p=>p.r===r).map(p=>`<div class="metric"><span>${RECIPES[p.type].name} #${p.id}<small style="display:block">${p.status||'Ожидает следующего дня'}</small></span><button onclick="togglePlant(${p.id})">${p.enabled?'Приостановить':'Запустить'}</button></div>`).join('')}</div>`;}
function buildPlant(r,type){if(!state.regions.includes(r)||!RECIPES[type])return;if(!spend(RECIPES[type].cost,'Строительство: '+RECIPES[type].name))return;const e=econInit();e.plants.push({id:e.nextPlant++,r,type,enabled:false,status:'Приостановлен'});render();notify('Завод построен. Закупите сырьё и включите производство.');}
function togglePlant(id){const p=econInit().plants.find(p=>p.id===id);if(p){p.enabled=!p.enabled;render()}}
const originalOverview=overview,originalNetwork=network,originalFinance=finances,originalJobs=jobs,originalFleet=fleet,originalHelp=help,originalNextDay=nextDay,originalRender=render,originalFixed=fixed;
fleet=()=>originalFleet().replace(/<span class="transport">([^<]*)<\/span>/g,(_,icon)=>vector(typeIcon(modes.findIndex(m=>m.icon===icon))));
help=()=>{originalHelp();$('#modal .help').insertAdjacentHTML('beforeend','<p><strong>7. Торгуйте и производите.</strong> В товарных рынках закупайте сырьё, запускайте заводы и продавайте готовую продукцию. Хранение стоит 2 $/т в день; продукты теряют 3% ежедневно. Для перевозки между рынками нужны открытый регион, свободное судно или самолёт и место на складе назначения. Товар по прибытии продаётся вручную.</p>');};
fixed=()=>originalFixed()+econInit().plants.length*150;
jobs=()=>{const html=originalJobs();let i=0;return html.replace(/<div class="route">/g,()=>shipmentVisual(state.jobs[i++])+'<div class="route">')};
network=()=>`<div class="panel"><div class="row"><h2>Схема логистической сети</h2><small>Пунктир — действующий рейс</small></div>${networkDiagram()}</div>`+originalNetwork();
overview=()=>originalOverview()+`<div class="panel"><div class="row"><h2>${vector('warehouse')} Торговля и производство</h2><button class="primary" onclick="openTab('market')">Открыть товарные рынки →</button></div><div class="metric"><span>Результат торговли с учётом хранения и потерь</span><strong>${money(econInit().profit)}</strong></div><div class="metric"><span>Запасы по себестоимости</span><strong>${money(Object.values(econInit().inventory).reduce((n,s)=>n+s.basis,0))}</strong></div><p>Доход от контрактов можно инвестировать в собственные товары и производственные цепочки.</p></div>`;
finances=()=>`<div class="panel"><h2>Торговый результат</h2><div class="metric"><span>Накопленный результат торговли</span><strong>${money(econInit().profit)}</strong></div><p>Включает реализованную маржу, хранение, порчу и содержание заводов. Себестоимость товаров включает закупку, обработку и доставку. Общие расходы транспорта, кредитов и контрактные доходы учитываются отдельно в журнале денежных операций.</p>${econInit().records.slice(0,6).map(l=>`<div class="metric"><span>Д${l.day} · ${l.text}</span><strong class="${l.profit>=0?'positive':'negative'}">${money(l.profit)}</strong></div>`).join('')}</div>`+originalFinance();
nextDay=()=>{econInit();const arrivals=state.jobs.filter(j=>j.trade&&j.remaining<=1).map(j=>({...j}));originalNextDay();for(const j of arrivals){const s=stock(j.d,j.trade.g);s.qty+=j.trade.qty;s.basis+=j.trade.basis;log('Товар на складе: '+GOODS[j.trade.g].name+' · '+regions[j.d].name)}const e=econInit();if(e.plants.length)recordProfit(-e.plants.length*150,'Содержание заводов');for(const p of e.plants){if(!p.enabled){p.status='Приостановлен';continue}const recipe=RECIPES[p.type],s=stock(p.r,recipe.input),needed=recipe.batch*recipe.ratio;if(s.qty+1e-8<needed){p.status='Нет сырья';continue}if(state.cash<recipe.labor){p.status='Нет оборотных средств';continue}if(load(p.r)-needed+recipe.batch>capacity(p.r)){p.status='Склад заполнен';continue}const basis=s.basis*needed/s.qty;s.qty-=needed;s.basis-=basis;const output=stock(p.r,recipe.output);output.qty+=recipe.batch;output.basis+=basis+recipe.labor;transaction(-recipe.labor,'Производство: '+recipe.name);p.status='Выпущено '+recipe.batch+' т за день';}let storage=0,loss=0;for(const r of state.regions){storage+=stockWeight(r)*2;for(let g=0;g<GOODS.length;g++){const s=stock(r,g),rate=GOODS[g].loss;if(rate&&s.qty){loss+=s.basis*rate;s.qty*=1-rate;s.basis*=1-rate;}}}if(storage){transaction(-storage,'Хранение товарных запасов');recordProfit(-storage,'Хранение');}if(loss){recordProfit(-loss,'Порча продуктов');log('Потери продуктов: '+money(loss));}e.storage+=storage;e.spoilage+=loss;for(const k of Object.keys(e.pressure))e.pressure[k]*=.8;state.history[state.history.length-1]=state.cash;render();};
render=()=>{econInit();if(tab==='market'){const previous=overview;overview=tradeView;tab='overview';originalRender();overview=previous;tab='market';$('h1').textContent='Товарные рынки';$('.topline p').textContent='Запасы, региональный спрос и производственные цепочки.';}else originalRender();const nav=$('nav');nav.insertAdjacentHTML('beforeend',`<button class="${tab==='market'?'active':''}" onclick="openTab('market')"><span>▧</span>Товарные рынки</button>`);if(tab==='market')nav.querySelector('button').classList.remove('active');save();};
render();
